mutations.replace:
export const cancelOrder = (store, id) => moved(store, id, "open", "cancelled");

// An order marked delivered, whatever state it was in.
export const deliverOrder = (store, id) => ((order) => (order ? store.put("orders", id, { ...order, state: "delivered" }) : { error: "NOT_FOUND" }))(getOrder(store, id));
